// Shared by the app's services (api.js, auth.js, worker.js). Generated by ARCHITECH from a design;
// app.config.json says which parts the design has and how they connect.

import { readFileSync } from "node:fs";
import http from "node:http";
import { Resolver } from "node:dns/promises";
import pg from "pg";

export const config = JSON.parse(readFileSync(process.env.APP_CONFIG ?? "/config/app.config.json", "utf8"));
export const SELF = process.env.CONTAINER ?? "service";
export const env = (name) => process.env[name] ?? "";

// ---- Tracing: what each part of the design did for a request ----
// A step names the design component (its id in ARCHITECH) and says what happened there.
// They travel back to the page in the X-Trace-Steps header, so every response carries them.
export const step = (node, text, extra = {}) => ({ node, text, ...extra });
export const encodeSteps = (steps) => encodeURIComponent(JSON.stringify(steps));
export function decodeSteps(header) {
  try {
    const parsed = JSON.parse(decodeURIComponent(header ?? "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function sendJson(response, status, body, steps = [], headers = {}) {
  response.writeHead(status, {
    "Content-Type": "application/json",
    "Cache-Control": "no-store",
    "X-Trace-Steps": encodeSteps(steps),
    ...headers,
  });
  response.end(JSON.stringify(body));
}

export async function readBody(request, limit = 64_000) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > limit) throw Object.assign(new Error("too large"), { status: 413 });
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

export async function readJson(request) {
  const raw = (await readBody(request)).toString("utf8");
  try {
    return JSON.parse(raw || "{}");
  } catch {
    throw Object.assign(new Error("bad json"), { status: 400 });
  }
}

export function cookies(header) {
  const out = {};
  for (const part of (header ?? "").split(";")) {
    const index = part.indexOf("=");
    if (index > 0) out[part.slice(0, index).trim()] = decodeURIComponent(part.slice(index + 1).trim());
  }
  return out;
}

export const ms = (since) => Math.round(performance.now() - since);
export const sleep = (time) => new Promise((resolve) => setTimeout(resolve, time));

// ---- The database (PostgreSQL), when the design has one ----
export const db = env("DATABASE_URL") ? new pg.Pool({ connectionString: env("DATABASE_URL"), max: 5 }) : null;

// Waits for a dependency that is still starting (the database, the cache...).
export async function waitFor(label, check, attempts = 60) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await check();
    } catch (error) {
      if (attempt >= attempts) throw error;
      if (attempt === 1) console.log(`${SELF}: waiting for ${label}…`);
      await sleep(1000);
    }
  }
}

// ---- Forwarding to the next part of the request path ----
// When the design puts a DNS server between this part and the next, the next part's address is
// looked up there (not with Docker's own DNS), so the page can show the answer.
export async function resolveNext(next) {
  if (!next.dns) return { host: next.host, answer: null };
  const resolver = new Resolver();
  resolver.setServers([next.dns.server]);
  const addresses = await resolver.resolve4(next.host);
  const address = addresses[Math.floor(Math.random() * addresses.length)];
  return { host: address, answer: address };
}

// Sends the request on, unchanged except for the given headers, and streams the answer back
// with this part's trace header and steps added.
export async function forward(request, response, next, { headers = {}, steps = [], body } = {}) {
  let target;
  try {
    target = await resolveNext(next);
  } catch {
    return sendJson(response, 502, { error: `DNS could not find ${next.host}.` }, [...steps, step(next.dns?.node ?? "", `No answer for ${next.host}.`, { ok: false })], {
      [`X-Trace-${SELF}`]: "dns-failed",
    });
  }
  const outgoing = { ...request.headers, ...headers, host: next.host };
  for (const [key, value] of Object.entries(outgoing)) if (value === undefined) delete outgoing[key];
  if (body !== undefined) outgoing["content-length"] = String(body.length);
  const upstream = http.request({ host: target.host, port: next.port, method: request.method, path: request.url, headers: outgoing }, (answer) => {
    const downstream = decodeSteps(answer.headers["x-trace-steps"]);
    const headersOut = { ...answer.headers, "x-trace-steps": encodeSteps([...steps, ...downstream]) };
    headersOut[`x-trace-${SELF}`.toLowerCase()] = `${target.host}:${next.port}`;
    response.writeHead(answer.statusCode ?? 502, headersOut);
    answer.pipe(response);
  });
  upstream.on("error", () => {
    if (response.headersSent) return response.end();
    sendJson(response, 502, { error: `${next.label} did not answer.` }, steps, { [`X-Trace-${SELF}`]: "-" });
  });
  if (body !== undefined) upstream.end(body);
  else request.pipe(upstream);
}
